clean_code:
def binary_search(arr, target):
    first, stop = 0, len(arr)
    while first < stop:
        middle = (first + stop) // 2
        if arr[middle] == target:
            return middle
        if arr[middle] < target:
            first = middle + 1
        else:
            stop = middle
    return -1

